from collections import deque
def shapes(grid):
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]; S=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                c=grid[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==c:
                            seen[ny][nx]=True; q.append((ny,nx))
                S.append((c,cells))
    return S

def slide_right(grid):
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    S=shapes(grid)
    S.sort(key=lambda s:-max(x for _,x in s[1]))
    for c,cells in S:
        cs=set(cells)
        while True:
            nxt=[(y,x+1) for y,x in cells]
            if any(x>=w or (out[y][x] and (y,x) not in cs) for y,x in nxt): break
            cells=nxt
        for y,x in cells: out[y][x]=c
    return out

